-- 3) ผูกอุปกรณ์ AV ตัวอย่างให้บางงาน (ตามตาราง equipment ที่ seed ไว้แล้ว)
INSERT INTO task_equipments (task_id, equipment_id, quantity)
SELECT t.id, e.id, 2
FROM tasks t
JOIN equipment e ON e.name = 'ไมค์ลอย' AND e.is_enabled = 1
WHERE t.title = 'ตั้งเวทีเสียงงานประชุมประจำเดือน'
LIMIT 1;

INSERT INTO task_equipments (task_id, equipment_id, quantity)
SELECT t.id, e.id, 1
FROM tasks t
JOIN equipment e ON e.name = 'โปรเจ็คเตอร์' AND e.is_enabled = 1
WHERE t.title = 'โปรเจ็คเตอร์ห้องประชุม B ภาพเบลอ'
LIMIT 1;

INSERT INTO task_equipments (task_id, equipment_id, quantity)
SELECT t.id, e.id, 4
FROM tasks t
JOIN equipment e ON e.name = 'ระบบเสียงหลักขององค์กร' AND e.is_enabled = 1
WHERE t.title = 'ซ้อมระบบภาพเสียงงานประชุมสุดท้ายปี'
LIMIT 1;

-- 4) ประวัติกิจกรรมเริ่มต้นให้ทุกงาน (โชว์แท็บ "ประวัติการเปลี่ยนแปลง" ได้ทันที)
INSERT INTO task_activity_logs (task_id, actor_user_id, actor_name, event_type, description)
SELECT id, created_by, COALESCE(responsible_name, 'ระบบ'), 'created', 'สร้างงานใหม่'
FROM tasks;
